import { test, expect } from 'vitest';
import { page } from 'vitest/browser';
import { renderFileList } from './file-list.js';

test('deletes the selected files', async () => {
  renderFileList(document.body, ['a.txt', 'b.txt', 'c.txt']);

  await page.getByRole('checkbox', { name: 'a.txt' }).click();
  await page.getByRole('checkbox', { name: 'b.txt' }).click();
  // The label also includes the selected count ("Delete 2 files"), so match only the word.
  await page.getByRole('button', { name: /\bDelete\b/ }).click();

  await expect.element(page.getByRole('checkbox', { name: 'a.txt' })).not.toBeInTheDocument();
  await expect.element(page.getByRole('checkbox', { name: 'b.txt' })).not.toBeInTheDocument();
  await expect.element(page.getByRole('checkbox', { name: 'c.txt' })).toBeInTheDocument();
  expect(page.getByRole('listitem').elements()).toHaveLength(1);
});

